Here's a Python script for automating Chinese OSINT searches:

```python
import requests
from bs4 import BeautifulSoup
import json

def baidu_search(query: str, num_results: int = 10) -> list:
    """Search Baidu for Chinese-language content."""
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8'
    }
    results = []
    for page in range(0, num_results, 10):
        url = f'https://www.baidu.com/s?wd={query}&pn={page}'
        try:
            resp = requests.get(url, headers=headers, timeout=10)
            soup = BeautifulSoup(resp.text, 'html.parser')
            for item in soup.find_all('div', class_='result'):
                title_tag = item.find('h3')
                link_tag = item.find('a')
                if title_tag and link_tag:
                    results.append({
                        'title': title_tag.get_text(),
                        'url': link_tag.get('href', ''),
                        'snippet': item.get_text()[:200]
                    })
        except Exception as e:
            print(f'Error on page {page}: {e}')
    return results

def tianyancha_search(company: str) -> dict:
    """Search Tianyancha for Chinese corporate data."""
    # Note: Tianyancha has API restrictions; this is illustrative
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
        'Accept-Language': 'zh-CN,zh;q=0.9'
    }
    search_url = f'https://www.tianyancha.com/search?key={company}'
    try:
        resp = requests.get(search_url, headers=headers, timeout=10)
        return {
            'status': resp.status_code,
            'company': company,
            'note': 'Full API access requires authentication'
        }
    except Exception as e:
        return {'error': str(e)}

# Example: Search for Huawei in Chinese
results = baidu_search('华为 网络安全 事件')
for r in results[:5]:
    print(f"Title: {r['title']}")
    print(f"URL: {r['url']}")
    print(f"Snippet: {r['snippet'][:100]}")
    print('---')
```

**Key Points:**
- Always set `Accept-Language: zh-CN` header for better Chinese results
- Use simplified Chinese for search queries targeting mainland China
- Tianyancha and Qichacha have anti-scraping measures — use their APIs where possible
- Rate-limit your requests to avoid IP bans
